void VkRenderAdapter::StartPass(VkRenderPass pass,VkFramebuffer frame,bool clear){VkClearValue values[2]{};values[1].depthStencil.depth=1;VkRenderPassBeginInfo begin{VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO};begin.renderPass=pass;begin.framebuffer=frame;begin.renderArea.extent=m_SwapExtent;begin.clearValueCount=clear?2:0;begin.pClearValues=values;vkCmdBeginRenderPass(m_CmdBuffers[m_ImageIndex],&begin,VK_SUBPASS_CONTENTS_INLINE);}
bool VkRenderAdapter::BeginViewmodelPass(){if(m_Skip||!m_Recording)return false;vkCmdEndRenderPass(m_CmdBuffers[m_ImageIndex]);StartPass(m_ViewmodelPass,m_ViewmodelFrames[m_ImageIndex],true);return true;}
void VkRenderAdapter::EndViewmodelPass(){vkCmdEndRenderPass(m_CmdBuffers[m_ImageIndex]);StartPass(m_ResumePass,m_Framebuffers[m_ImageIndex],false);}
