void VkRenderAdapter::DestroyTexture(RenderTextureHandle h){auto it=m_Textures.find(h.value);if(it==m_Textures.end())return;m_RetiredTextures[m_Recording?m_Frame:m_LastSubmittedFrame].push_back(std::move(it->second));m_Textures.erase(it);if(m_Texture==h)m_Texture=m_White;}
RenderShaderHandle VkRenderAdapter::CreateShaderProgram(const ShaderResource& s){if(s.placeholder||s.sourcePath=="dx12/textured.hlsl")return {1};Logger::Get().Warn("Vulkan supports the built-in textured material program; custom shader skipped: "+s.name);return {};}
void VkRenderAdapter::DrawMesh(RenderMeshHandle handle){if(m_Skip||!m_Recording)return;auto it=m_Meshes.find(handle.value);if(it==m_Meshes.end())return;auto& mesh=it->second;auto texture=m_Textures.find(m_Texture.value);if(texture==m_Textures.end())texture=m_Textures.find(m_White.value);if(texture==m_Textures.end())return;auto command=m_CmdBuffers[m_ImageIndex];vkCmdBindPipeline(command,VK_PIPELINE_BIND_POINT_GRAPHICS,m_ScenePso[m_Material.doubleSided?2:m_Material.reverseWinding?1:0]);VkRect2D clip{{0,0},m_SwapExtent};vkCmdSetScissor(command,0,1,&clip);vkCmdBindDescriptorSets(command,VK_PIPELINE_BIND_POINT_GRAPHICS,m_SceneLayout,0,1,&texture->second.set,0,nullptr);std::array<float,24> constants;std::copy(m_PendingMVP,m_PendingMVP+16,constants.begin());std::copy(m_PendingColor,m_PendingColor+4,constants.begin()+16);std::copy(m_BaseColor.begin(),m_BaseColor.end(),constants.begin()+20);vkCmdPushConstants(command,m_SceneLayout,VK_SHADER_STAGE_VERTEX_BIT|VK_SHADER_STAGE_FRAGMENT_BIT,0,96,constants.data());VkDeviceSize offset=0;vkCmdBindVertexBuffers(command,0,1,&mesh.vertices.buffer,&offset);vkCmdBindIndexBuffer(command,mesh.indices.buffer,0,VK_INDEX_TYPE_UINT32);auto count=m_Range.indexCount?m_Range.indexCount:uint32_t(mesh.source.indices.size());if(m_Range.firstIndex+count>mesh.source.indices.size())return;vkCmdDrawIndexed(command,count,1,m_Range.firstIndex,0,0);++m_Statistics.drawCalls;++m_Statistics.renderedInstances;}
void VkRenderAdapter::DrawRuntimeUI(const ui::DrawList& draw){if(m_Skip||!m_Recording||draw.width<1||draw.height<1||draw.vertices.empty())return;auto bytes=draw.vertices.size()*sizeof(ui::Vertex);auto& buffer=m_UIBuffers[m_Frame];if(buffer.capacity<m_UIUsed+bytes){if(buffer.buffer){Mesh retired;retired.vertices=buffer;m_RetiredMeshes[m_Frame].push_back(std::move(retired));}buffer=MakeBuffer(std::max(VkDeviceSize(65536),2*(m_UIUsed+bytes)),VK_BUFFER_USAGE_VERTEX_BUFFER_BIT);}void* data;Check(vkMapMemory(m_Device,buffer.memory,0,buffer.capacity,0,&data));std::memcpy(static_cast<char*>(data)+m_UIUsed,draw.vertices.data(),bytes);vkUnmapMemory(m_Device,buffer.memory);auto command=m_CmdBuffers[m_ImageIndex];vkCmdBindPipeline(command,VK_PIPELINE_BIND_POINT_GRAPHICS,m_UIPso);std::array<float,24> constants{};constants[0]=2/draw.width;constants[5]=-2/draw.height;constants[10]=constants[15]=1;constants[12]=-1;constants[13]=1;vkCmdPushConstants(command,m_SceneLayout,VK_SHADER_STAGE_VERTEX_BIT|VK_SHADER_STAGE_FRAGMENT_BIT,0,96,constants.data());VkDeviceSize offset=m_UIUsed;vkCmdBindVertexBuffers(command,0,1,&buffer.buffer,&offset);for(auto& part:draw.commands){auto it=m_Textures.find(part.texture.value);if(it==m_Textures.end()||part.first+part.count>draw.vertices.size())continue;auto x=int(std::max(0.f,std::floor(part.clip.x))),y=int(std::max(0.f,std::floor(part.clip.y)));int right=int(std::min(draw.width,std::ceil(part.clip.x+part.clip.w))),bottom=int(std::min(draw.height,std::ceil(part.clip.y+part.clip.h)));if(right<=x||bottom<=y)continue;VkRect2D clip{{x,y},{unsigned(right-x),unsigned(bottom-y)}};vkCmdSetScissor(command,0,1,&clip);vkCmdBindDescriptorSets(command,VK_PIPELINE_BIND_POINT_GRAPHICS,m_SceneLayout,0,1,&it->second.set,0,nullptr);vkCmdDraw(command,part.count,1,part.first,0);}m_UIUsed+=bytes;}
void VkRenderAdapter::RetireSubmission(){for(auto& mesh:m_RetiredMeshes[m_Frame]){FreeBuffer(mesh.vertices);FreeBuffer(mesh.indices);}m_RetiredMeshes[m_Frame].clear();for(auto& texture:m_RetiredTextures[m_Frame]){vkFreeDescriptorSets(m_Device,m_TexturePool,1,&texture.set);FreeImage(texture.gpu);}m_RetiredTextures[m_Frame].clear();}
void VkRenderAdapter::ReleaseSubmission(){for(auto& [id,mesh]:m_Meshes){FreeBuffer(mesh.vertices);FreeBuffer(mesh.indices);}m_Meshes.clear();for(auto& [id,texture]:m_Textures){vkFreeDescriptorSets(m_Device,m_TexturePool,1,&texture.set);FreeImage(texture.gpu);}m_Textures.clear();for(int i=0;i<2;++i){m_Frame=i;RetireSubmission();FreeBuffer(m_UIBuffers[i]);FreeBuffer(m_Readback[i]);}for(auto& pipeline:m_ScenePso){if(pipeline)vkDestroyPipeline(m_Device,pipeline,nullptr);pipeline=VK_NULL_HANDLE;}if(m_UIPso)vkDestroyPipeline(m_Device,m_UIPso,nullptr);if(m_SceneLayout)vkDestroyPipelineLayout(m_Device,m_SceneLayout,nullptr);if(m_TexturePool)vkDestroyDescriptorPool(m_Device,m_TexturePool,nullptr);if(m_TextureLayout)vkDestroyDescriptorSetLayout(m_Device,m_TextureLayout,nullptr);if(m_TextureSampler)vkDestroySampler(m_Device,m_TextureSampler,nullptr);m_UIPso=VK_NULL_HANDLE;m_SceneLayout=VK_NULL_HANDLE;m_TexturePool=VK_NULL_HANDLE;m_TextureLayout=VK_NULL_HANDLE;m_TextureSampler=VK_NULL_HANDLE;m_White={};m_Texture={};}
void VkRenderAdapter::CopyReadback(){if(!m_ReadbackEnabled)return;if(m_SwapFormat!=VK_FORMAT_B8G8R8A8_UNORM&&m_SwapFormat!=VK_FORMAT_R8G8B8A8_UNORM&&m_SwapFormat!=VK_FORMAT_B8G8R8A8_SRGB&&m_SwapFormat!=VK_FORMAT_R8G8B8A8_SRGB)throw std::runtime_error("Vulkan readback requires an 8-bit RGBA/BGRA swapchain");VkSurfaceCapabilitiesKHR capabilities{};Check(vkGetPhysicalDeviceSurfaceCapabilitiesKHR(m_Physical,m_Surface,&capabilities));if(!(capabilities.supportedUsageFlags&VK_IMAGE_USAGE_TRANSFER_SRC_BIT))throw std::runtime_error("Vulkan surface does not support GPU readback");auto bytes=VkDeviceSize(m_SwapExtent.width)*m_SwapExtent.height*4;auto& buffer=m_Readback[m_Frame];if(buffer.capacity<bytes){FreeBuffer(buffer);buffer=MakeBuffer(bytes,VK_BUFFER_USAGE_TRANSFER_DST_BIT);}auto command=m_CmdBuffers[m_ImageIndex];VkImageMemoryBarrier barrier{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};barrier.srcQueueFamilyIndex=barrier.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;barrier.image=m_SwapImages[m_ImageIndex];barrier.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};barrier.oldLayout=VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;barrier.newLayout=VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;barrier.srcAccessMask=VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;barrier.dstAccessMask=VK_ACCESS_TRANSFER_READ_BIT;vkCmdPipelineBarrier(command,VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,0,0,nullptr,0,nullptr,1,&barrier);VkBufferImageCopy copy{};copy.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};copy.imageExtent={m_SwapExtent.width,m_SwapExtent.height,1};vkCmdCopyImageToBuffer(command,barrier.image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,buffer.buffer,1,&copy);VkBufferMemoryBarrier host{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};host.srcQueueFamilyIndex=host.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED;host.buffer=buffer.buffer;host.size=VK_WHOLE_SIZE;host.srcAccessMask=VK_ACCESS_TRANSFER_WRITE_BIT;host.dstAccessMask=VK_ACCESS_HOST_READ_BIT;vkCmdPipelineBarrier(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_HOST_BIT,0,0,nullptr,1,&host,0,nullptr);barrier.oldLayout=VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;barrier.newLayout=VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;barrier.srcAccessMask=VK_ACCESS_TRANSFER_READ_BIT;barrier.dstAccessMask=0;vkCmdPipelineBarrier(command,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT,0,0,nullptr,0,nullptr,1,&barrier);m_LastReadback=m_Frame;}
std::vector<unsigned char> VkRenderAdapter::ReadBackPixels(){Check(vkDeviceWaitIdle(m_Device));auto& buffer=m_Readback[m_LastReadback];if(!buffer.buffer)return {};std::vector<unsigned char> result(size_t(m_SwapExtent.width)*m_SwapExtent.height*4);void* data;Check(vkMapMemory(m_Device,buffer.memory,0,buffer.capacity,0,&data));std::memcpy(result.data(),data,result.size());vkUnmapMemory(m_Device,buffer.memory);if(m_SwapFormat==VK_FORMAT_B8G8R8A8_UNORM||m_SwapFormat==VK_FORMAT_B8G8R8A8_SRGB)for(size_t i=0;i<result.size();i+=4)std::swap(result[i],result[i+2]);return result;}
void VkRenderAdapter::RecreateWindow(){auto* window=m_Window;std::map<std::uint64_t,MeshData> meshes;std::map<std::uint64_t,TextureData> textures;for(auto& [id,mesh]:m_Meshes)meshes[id]=mesh.source;for(auto& [id,texture]:m_Textures)if(id!=m_White.value)textures[id]=texture.source;Shutdown();if(!Initialize(window))throw std::runtime_error("Vulkan swapchain recreation failed");for(auto& [id,data]:meshes){auto h=UploadMesh(data);auto node=m_Meshes.extract(h.value);node.key()=id;m_Meshes.insert(std::move(node));}for(auto& [id,data]:textures){auto h=CreateTexture2D(data);auto node=m_Textures.extract(h.value);node.key()=id;m_Textures.insert(std::move(node));}}
